/* 00000324-00000490       .text setPointLight__21daObjTapestryPLight_cF4cXyz5csXyz */
void daObjTapestryPLight_c::setPointLight(cXyz pos, csXyz angle) {
    cLib_addCalc2(&mIntensity, 1.0f + cM_rndF(0.5f), 0.5f, 0.04f);
    mLight.mPos = pos;
    mLight.mColor.r = 600;
    mLight.mColor.g = 400;
    mLight.mColor.b = 120;
    mLight.mPower = (s16)(800.0f * mIntensity);
    mLight.mFluctuation = 250.0f;
    if (mIntensity > 1.0f) {
        f32 s = 1.5f * mIntensity;
        cXyz scl(s, s, s);
        if (mpEmitter == NULL) {
            mpEmitter = dComIfGp_particle_setProjection(0x4004, &pos, &angle, &scl);
        } else {
            mpEmitter->setGlobalParticleScale(scl);
            mpEmitter->setEmitterCallBackPtr(dPa_control_c::getKageroEcallBack());
        }
    }
}

/* 00000490-00000600       .text execute__22daObjTapestryFireEff_cFP14JPABaseEmitter */
void daObjTapestryFireEff_c::execute(JPABaseEmitter* emitter) {
    f32 lim = attr().m50;
    cXyz vel = mSpd * attr().m4C;
    vel.x = cLib_minMaxLimit<f32>(vel.x, -lim, lim);
    vel.z = cLib_minMaxLimit<f32>(vel.z, -lim, lim);
    emitter->setDirection(JGeometry::TVec3<f32>(vel.x, 0.1f, vel.z));
    dPa_followEcallBack::execute(emitter);
}

