void daObjTapestryPacket_c::calc_acc_spring_sub(const cXyz* p1, const cXyz* p2, float rest, float stiff) {
    cXyz diff(p1->x - p2->x, p1->y - p2->y, p1->z - p2->z);
    f32 mag = diff.abs();
    if (mag > 0.01f) {
        mAcc += (diff * ((mag - rest) * -attr().m04 * stiff)) / (mag * attr().m00);
    }
}

